params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
$branch='integrate/heaven-local-bridge-main-20260929-a1'
$tmp=Join-Path $env:TEMP 'mhw-heaven-bridge-main-20260929-a1'
Set-Location $repo
git fetch origin --prune
if (Test-Path $tmp) {
  try { git worktree remove --force $tmp | Out-Null } catch {}
  if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
}
git branch -D $branch 2>$null | Out-Null
git worktree add -b $branch $tmp origin/main
Set-Location $tmp
git checkout origin/heaven-bridge -- .github/workflows/heaven-bridge-gate.yml heaven-bridge/README.md heaven-bridge/bootstrap.ps1 heaven-bridge/manage.ps1 heaven-bridge/test_worker.py heaven-bridge/tests/test_worker.py heaven-bridge/worker.py

$wf = Join-Path $tmp '.github\workflows\heaven-bridge-gate.yml'
$wfText = [IO.File]::ReadAllText($wf)
$wfText = $wfText -replace "branches:\r?\n      - heaven-bridge", "branches:`n      - main`n      - heaven-bridge"
[IO.File]::WriteAllText($wf, $wfText, (New-Object Text.UTF8Encoding($false)))

$readme = Join-Path $tmp 'heaven-bridge\README.md'
$readmeText = [IO.File]::ReadAllText($readme)
$readmeText = $readmeText -replace "ChatGPT\r?\n  -> private GitHub relay \(fengie/mhw-mods, branch heaven-bridge\)", "ChatGPT`n  -> private GitHub relay (fengie/mhw-mods, transport branch heaven-bridge)"
$readmeText = $readmeText -replace "## Worker v3\r?\n\r?\n`heaven-bridge/worker\.py` is the repository source of truth\.", "## Worker v3`n`nCanonical bridge source lives on `main`. The `heaven-bridge` branch is the private transport/relay channel for queue, status, and result records. `heaven-bridge/worker.py` is the worker source path mirrored to the relay runtime."
[IO.File]::WriteAllText($readme, $readmeText, (New-Object Text.UTF8Encoding($false)))

$python=(Get-Command python.exe -ErrorAction Stop).Source
& $python -m py_compile heaven-bridge\worker.py heaven-bridge\test_worker.py heaven-bridge\tests\test_worker.py
if($LASTEXITCODE -ne 0){throw "py_compile failed $LASTEXITCODE"}
& $python -m unittest -v heaven-bridge\test_worker.py
if($LASTEXITCODE -ne 0){throw "primary tests failed $LASTEXITCODE"}
& $python -m unittest -v heaven-bridge\tests\test_worker.py
if($LASTEXITCODE -ne 0){throw "compat tests failed $LASTEXITCODE"}
foreach($p in @('heaven-bridge\bootstrap.ps1','heaven-bridge\manage.ps1')){
  $tokens=$null;$errors=$null
  [void][Management.Automation.Language.Parser]::ParseFile((Resolve-Path $p),[ref]$tokens,[ref]$errors)
  if($errors.Count -gt 0){throw (($errors|Out-String))}
}
git diff --check
if($LASTEXITCODE -ne 0){throw "git diff --check failed"}
git add .github/workflows/heaven-bridge-gate.yml heaven-bridge/README.md heaven-bridge/bootstrap.ps1 heaven-bridge/manage.ps1 heaven-bridge/test_worker.py heaven-bridge/tests/test_worker.py heaven-bridge/worker.py
git commit -m "Add Heaven Local Bridge to canonical main"
if($LASTEXITCODE -ne 0){throw "commit failed"}
git push -u origin $branch
if($LASTEXITCODE -ne 0){throw "push failed"}
[ordered]@{
  branch=$branch
  head=(git rev-parse HEAD)
  base=(git rev-parse origin/main)
  status=@(git status --short)
  stat=@(git diff --stat origin/main...HEAD)
}|ConvertTo-Json -Depth 4
